-- PostgreSQL/JSONB authority, version 1. Only explicitly provisioned team schemas.
CREATE TABLE IF NOT EXISTS team (singleton BIGINT PRIMARY KEY CHECK(singleton=1), record JSONB NOT NULL, __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS controller (singleton BIGINT PRIMARY KEY CHECK(singleton=1), instance_id TEXT NOT NULL, fence BIGINT NOT NULL, token_hash TEXT NOT NULL, expires_at DOUBLE PRECISION NOT NULL, __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS agents (id TEXT PRIMARY KEY, role TEXT NOT NULL CHECK(role IN ('lead','coordinator','worker')), state TEXT NOT NULL, active BIGINT NOT NULL DEFAULT 1, token_hash TEXT NOT NULL, record JSONB NOT NULL, __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, state TEXT NOT NULL CHECK(state IN ('ready','running','blocked','succeeded','failed','canceled')), owner_id TEXT REFERENCES agents(id), fence BIGINT NOT NULL DEFAULT 0, record JSONB NOT NULL, __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS dependencies (task_id TEXT NOT NULL REFERENCES tasks(id), depends_on TEXT NOT NULL REFERENCES tasks(id), PRIMARY KEY(task_id,depends_on), CHECK(task_id<>depends_on), __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS attempts (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), agent_id TEXT NOT NULL REFERENCES agents(id), fence BIGINT NOT NULL, controller_fence BIGINT NOT NULL, state TEXT NOT NULL, heartbeat_at DOUBLE PRECISION NOT NULL, started_at DOUBLE PRECISION NOT NULL, finished_at DOUBLE PRECISION, reason TEXT NOT NULL DEFAULT '', UNIQUE(task_id,fence), __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_attempt ON attempts(task_id) WHERE state='running';
CREATE TABLE IF NOT EXISTS reservations (id TEXT PRIMARY KEY, request_key TEXT NOT NULL, agent_id TEXT NOT NULL REFERENCES agents(id), task_id TEXT, task_fence BIGINT NOT NULL, controller_fence BIGINT NOT NULL, tokens TEXT NOT NULL, cost_microusd TEXT NOT NULL, actual_tokens TEXT, actual_cost_microusd TEXT, state TEXT NOT NULL, created_at DOUBLE PRECISION NOT NULL, closed_at DOUBLE PRECISION, UNIQUE(agent_id,request_key), __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, sender_id TEXT NOT NULL REFERENCES agents(id), task_id TEXT NOT NULL REFERENCES tasks(id), request_key TEXT NOT NULL, intent TEXT NOT NULL, topic TEXT NOT NULL, priority BIGINT NOT NULL, created_at DOUBLE PRECISION NOT NULL, expires_at DOUBLE PRECISION NOT NULL, record JSONB NOT NULL, UNIQUE(sender_id,request_key), __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE INDEX IF NOT EXISTS messages_task ON messages(task_id,created_at);
CREATE TABLE IF NOT EXISTS deliveries (message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, recipient_id TEXT NOT NULL REFERENCES agents(id), acknowledged_at DOUBLE PRECISION, lease_until DOUBLE PRECISION NOT NULL DEFAULT 0, deliveries BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(message_id,recipient_id), __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE INDEX IF NOT EXISTS deliveries_recipient ON deliveries(recipient_id,acknowledged_at,lease_until);
CREATE TABLE IF NOT EXISTS subscriptions (agent_id TEXT NOT NULL REFERENCES agents(id), task_id TEXT NOT NULL, topic TEXT NOT NULL, PRIMARY KEY(agent_id,task_id,topic), __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS artifacts (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES agents(id), task_id TEXT NOT NULL REFERENCES tasks(id), object_key TEXT NOT NULL, sha256 TEXT NOT NULL, size_bytes TEXT NOT NULL, request_key TEXT NOT NULL, pinned BIGINT NOT NULL DEFAULT 0, record JSONB NOT NULL, UNIQUE(owner_id,request_key), __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS verifications (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), fence BIGINT NOT NULL, accepted BIGINT NOT NULL, record JSONB NOT NULL, UNIQUE(task_id,fence), __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS ratings (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id), task_id TEXT NOT NULL REFERENCES tasks(id), evidence_key TEXT NOT NULL UNIQUE, record JSONB NOT NULL, __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE INDEX IF NOT EXISTS ratings_agent ON ratings(agent_id);
CREATE TABLE IF NOT EXISTS reputation (agent_id TEXT NOT NULL REFERENCES agents(id), domain TEXT NOT NULL, record JSONB NOT NULL, PRIMARY KEY(agent_id,domain), __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS team_tools (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, owner_id TEXT NOT NULL REFERENCES agents(id), state TEXT NOT NULL, record JSONB NOT NULL, __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS destinations (id TEXT PRIMARY KEY, record JSONB NOT NULL, __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS publications (id TEXT PRIMARY KEY, request_key TEXT NOT NULL UNIQUE, destination_id TEXT NOT NULL REFERENCES destinations(id), artifact_id TEXT NOT NULL REFERENCES artifacts(id), state TEXT NOT NULL, record JSONB NOT NULL, __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS decisions (id TEXT PRIMARY KEY, request_key TEXT NOT NULL UNIQUE, record JSONB NOT NULL, __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS counters (name TEXT PRIMARY KEY, value TEXT NOT NULL, __swarm_order BIGINT GENERATED ALWAYS AS IDENTITY);
CREATE TABLE IF NOT EXISTS events (seq BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, id TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, agent_id TEXT, task_id TEXT, trace_id TEXT NOT NULL, created_at DOUBLE PRECISION NOT NULL, record JSONB NOT NULL);
CREATE INDEX IF NOT EXISTS events_task ON events(task_id,seq);
CREATE INDEX IF NOT EXISTS tasks_state_owner ON tasks(state,owner_id);
CREATE INDEX IF NOT EXISTS dependencies_parent ON dependencies(depends_on,task_id);
CREATE INDEX IF NOT EXISTS attempts_recovery ON attempts(state,controller_fence,heartbeat_at);
CREATE INDEX IF NOT EXISTS agents_eligible ON agents(active,state,role);
CREATE INDEX IF NOT EXISTS publications_pending ON publications(state);
CREATE UNIQUE INDEX IF NOT EXISTS team_tools_operation ON team_tools(owner_id,(record->>'request_key'));
